CREATE TYPE "support_knowledge_status" AS ENUM ('draft', 'published', 'archived');
CREATE TYPE "support_chatbot_session_status" AS ENUM ('active', 'handed_off');
CREATE TYPE "support_chatbot_actor_type" AS ENUM ('customer', 'visitor', 'bot');
CREATE TYPE "support_chatbot_outcome" AS ENUM ('answered', 'insufficient_knowledge', 'ai_failed');
CREATE TABLE "support_knowledge_articles" ("id" uuid PRIMARY KEY, "project_id" uuid NOT NULL REFERENCES "support_projects"("id") ON DELETE CASCADE, "title" text NOT NULL, "source_key" text NOT NULL, "summary" text NOT NULL, "body" text NOT NULL, "status" support_knowledge_status NOT NULL, "revision_number" integer NOT NULL DEFAULT 0, "active_revision_number" integer, "tags" jsonb NOT NULL DEFAULT '[]', "created_by_agent_id" uuid NOT NULL, "updated_by_agent_id" uuid NOT NULL, "published_at" timestamptz, "archived_at" timestamptz, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, UNIQUE("project_id", "id"), UNIQUE("project_id", "source_key"));
CREATE TABLE "support_knowledge_revisions" ("id" uuid PRIMARY KEY, "project_id" uuid NOT NULL REFERENCES "support_projects"("id") ON DELETE CASCADE, "article_id" uuid NOT NULL, "revision_number" integer NOT NULL, "title" text NOT NULL, "summary" text NOT NULL, "body" text NOT NULL, "created_by_agent_id" uuid NOT NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, FOREIGN KEY("project_id", "article_id") REFERENCES "support_knowledge_articles"("project_id", "id") ON DELETE CASCADE, UNIQUE("project_id", "article_id", "revision_number"));
CREATE TABLE "support_knowledge_chunks" ("id" uuid PRIMARY KEY, "project_id" uuid NOT NULL REFERENCES "support_projects"("id") ON DELETE CASCADE, "article_id" uuid NOT NULL, "revision_number" integer NOT NULL, "chunk_index" integer NOT NULL, "source_key" text NOT NULL, "title" text NOT NULL, "section" text, "content" text NOT NULL, "character_count" integer NOT NULL, "checksum" text NOT NULL, "search_text" text NOT NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, FOREIGN KEY("project_id", "article_id") REFERENCES "support_knowledge_articles"("project_id", "id") ON DELETE CASCADE, UNIQUE("project_id", "article_id", "revision_number", "chunk_index"));
CREATE INDEX "support_knowledge_chunks_fts_idx" ON "support_knowledge_chunks" USING gin (to_tsvector('simple', "search_text"));
CREATE TABLE "support_chatbot_sessions" ("id" uuid PRIMARY KEY, "project_id" uuid NOT NULL REFERENCES "support_projects"("id") ON DELETE CASCADE, "actor_type" support_participant_type NOT NULL, "actor_id" uuid NOT NULL, "status" support_chatbot_session_status NOT NULL, "conversation_id" uuid, "turn_count" integer NOT NULL DEFAULT 0, "handed_off_at" timestamptz, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, CONSTRAINT "support_chatbot_sessions_customer_actor_check" CHECK ("actor_type" in ('customer', 'visitor')), UNIQUE("project_id", "id"));
CREATE TABLE "support_chatbot_turns" ("id" uuid PRIMARY KEY, "project_id" uuid NOT NULL REFERENCES "support_projects"("id") ON DELETE CASCADE, "session_id" uuid NOT NULL, "actor_type" support_chatbot_actor_type NOT NULL, "client_message_id" varchar(200), "content" text NOT NULL, "citations" jsonb NOT NULL DEFAULT '[]', "outcome" support_chatbot_outcome NOT NULL, "model_reference" text, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, FOREIGN KEY("project_id", "session_id") REFERENCES "support_chatbot_sessions"("project_id", "id") ON DELETE CASCADE);
CREATE UNIQUE INDEX "support_chatbot_turns_customer_idempotency_idx" ON "support_chatbot_turns" ("project_id", "session_id", "client_message_id") WHERE "client_message_id" is not null;
CREATE TABLE "support_chatbot_handoffs" ("id" uuid PRIMARY KEY, "project_id" uuid NOT NULL REFERENCES "support_projects"("id") ON DELETE CASCADE, "session_id" uuid NOT NULL, "conversation_id" uuid NOT NULL, "reason" text NOT NULL, "summary" text NOT NULL, "unresolved_questions" jsonb NOT NULL DEFAULT '[]', "cited_source_keys" jsonb NOT NULL DEFAULT '[]', "requested_at" timestamptz NOT NULL, "created_at" timestamptz NOT NULL, "updated_at" timestamptz NOT NULL, FOREIGN KEY("project_id", "session_id") REFERENCES "support_chatbot_sessions"("project_id", "id") ON DELETE CASCADE, UNIQUE("project_id", "session_id"));
